--[[
  Onyx Captions 1.0.0 installer for DaVinci Resolve Studio

  To install: in DaVinci Resolve choose Workspace > Console, then drag this
  file into the Console window. Run it again later to update or uninstall.

  It copies the extension into Resolve's Workflow Integration Plugins folder
  and nothing else. The extension's files are stored at the end of this file.
]]

local VERSION = "1.0.0"
local PLUGIN_ID = "com.onyxcaptions.resolve"
local MIN_RESOLVE = { 21, 1 }

local F = fu or fusion
local SEP = package.config:sub(1, 1)
-- Resolve's Lua is LuaJIT, which names the system: "Windows", "OSX" or "Linux"
local OS = jit and jit.os or (SEP == "\\" and "Windows" or "OSX")
local IS_WINDOWS, IS_MAC = OS == "Windows", OS == "OSX"
local FILES, FONTS -- filled in at the end of this file

-- automated runs (tests) set this instead of clicking a button
local AUTO = F:GetData("OnyxCaptionsInstaller.Action")
if AUTO then F:SetData("OnyxCaptionsInstaller.Action", nil) end

local function log(msg)
  print("[Onyx Captions] " .. msg)
end

local function join(...)
  return table.concat({ ... }, SEP)
end

local SUPPORT = IS_WINDOWS and join(os.getenv("PROGRAMDATA") or "C:\\ProgramData", "Blackmagic Design", "DaVinci Resolve", "Support")
  or "/Library/Application Support/Blackmagic Design/DaVinci Resolve"
local PLUGINS_DIR = join(SUPPORT, "Workflow Integration Plugins")
local TARGET = join(PLUGINS_DIR, "Onyx Captions")
-- Resolve's own module that lets the extension talk to Resolve
local SDK_MODULE = join(SUPPORT, "Developer", "Workflow Integrations", "Examples", "SamplePlugin", "WorkflowIntegration.node")
-- the caption fonts go where fonts installed "for me" go, so no admin is needed
local HOME = os.getenv(IS_WINDOWS and "USERPROFILE" or "HOME") or ""
local USER_FONTS = IS_WINDOWS and join(os.getenv("LOCALAPPDATA") or join(HOME, "AppData", "Local"), "Microsoft", "Windows", "Fonts")
  or join(HOME, "Library", "Fonts")
local SYSTEM_FONTS = IS_WINDOWS and join(os.getenv("WINDIR") or "C:\\Windows", "Fonts") or "/Library/Fonts"

-- base64, the way the extension's files are stored below
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local DEC = {}
for i = 1, 64 do DEC[B64:byte(i)] = i - 1 end

local function decode(s)
  s = s:gsub("[^%w%+/=]", "")
  local out, n, char, floor = {}, 0, string.char, math.floor
  for i = 1, #s, 4 do
    local a, b, c, d = s:byte(i, i + 3)
    local x = DEC[a] * 262144 + DEC[b] * 4096 + (DEC[c] or 0) * 64 + (DEC[d] or 0)
    local b1, b2, b3 = floor(x / 65536), floor(x / 256) % 256, x % 256
    n = n + 1
    if c == 61 then out[n] = char(b1)
    elseif d == 61 then out[n] = char(b1, b2)
    else out[n] = char(b1, b2, b3) end
  end
  return table.concat(out)
end

local function readFile(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local data = f:read("*a")
  f:close()
  return data
end

local function writeFile(path, data)
  local dir = path:match("^(.*)[\\/]")
  if dir and not bmd.direxists(dir) then bmd.createdir(dir) end
  local f, err = io.open(path, "wb")
  if not f then error("Couldn't write " .. path .. " (" .. tostring(err) .. ")", 0) end
  f:write(data)
  f:close()
end

-- bmd.removedir only removes empty folders
local function removeTree(dir)
  if not bmd.direxists(dir) then return true end
  for _, e in ipairs(bmd.readdir(join(dir, "*")) or {}) do
    local p = join(dir, e.Name)
    if e.IsDir then removeTree(p) else os.remove(p) end
  end
  return bmd.removedir(dir)
end

local function canWrite(dir)
  if not bmd.direxists(dir) then bmd.createdir(dir) end
  local probe = join(dir, ".onyx-write-test")
  local f = io.open(probe, "wb")
  if not f then return false end
  f:close()
  os.remove(probe)
  return true
end

local function shellQuote(s)
  return "'" .. s:gsub("'", "'\\''") .. "'"
end

-- On macOS the plugins folder can belong to the system. Then macOS asks for an
-- administrator password once, to create the extension's folder and give it to
-- this user; updates and uninstalling work without a password after that.
local function ensureWritable()
  if canWrite(TARGET) then return end
  if IS_MAC then
    local user = os.getenv("USER")
    if not user or user == "" then
      local p = io.popen("id -un")
      user = p and p:read("*l") or ""
      if p then p:close() end
    end
    local cmd = "mkdir -p " .. shellQuote(TARGET) .. " && chown -R " .. shellQuote(user) .. " " .. shellQuote(TARGET)
    local script = 'do shell script "' .. cmd:gsub('[\\"]', "\\%0") .. '" with administrator privileges'
    os.execute("osascript -e " .. shellQuote(script))
    if canWrite(TARGET) then return end
    error("Couldn't get permission to write to " .. TARGET .. ".", 0)
  end
  error("Couldn't write to " .. TARGET .. ".", 0)
end

local function installedVersion()
  local manifest = readFile(join(TARGET, "manifest.xml"))
  if not manifest or not manifest:find(PLUGIN_ID, 1, true) then return nil end
  local pkg = readFile(join(TARGET, "package.json")) or ""
  return pkg:match('"version"%s*:%s*"([^"]+)"') or "unknown"
end

-- nil when this computer can run the extension, otherwise why not
local function problem()
  if not (IS_WINDOWS or IS_MAC) then
    return "Onyx Captions runs on Windows and macOS. DaVinci Resolve on " .. OS .. " can't run extensions."
  end
  local resolve = Resolve()
  local product = resolve and resolve:GetProductName() or ""
  if not product:find("Studio", 1, true) then
    return "Onyx Captions needs DaVinci Resolve Studio. The free version of DaVinci Resolve can't run extensions."
  end
  local v = resolve:GetVersion() or {}
  local major, minor = tonumber(v[1]) or 0, tonumber(v[2]) or 0
  if major < MIN_RESOLVE[1] or (major == MIN_RESOLVE[1] and minor < MIN_RESOLVE[2]) then
    return string.format("Onyx Captions needs DaVinci Resolve Studio %d.%d or newer. This is version %d.%d.", MIN_RESOLVE[1], MIN_RESOLVE[2], major, minor)
  end
  if not bmd.fileexists(SDK_MODULE) then
    return "DaVinci Resolve's Workflow Integration files are missing (" .. SDK_MODULE .. "). Reinstall DaVinci Resolve Studio, then run this installer again."
  end
  return nil
end

-- Installs the presets' fonts for this user unless this computer has them
-- already, and returns the families it added. Uninstalling leaves them, so
-- projects that use them keep their look.
local function installFonts()
  local added, families, registry = {}, {}, {}
  for _, font in ipairs(FONTS) do
    local path = join(USER_FONTS, font.file)
    if not bmd.fileexists(path) and not bmd.fileexists(join(SYSTEM_FONTS, font.file)) then
      writeFile(path, decode(font.data))
      local family = font.file:match("^[^-]+")
      if not added[family] then
        added[family] = true
        families[#families + 1] = family
      end
    end
    -- Windows only lists a user's fonts that are registered; registering again is harmless
    if IS_WINDOWS and bmd.fileexists(path) then
      registry[#registry + 1] = string.format('reg add "HKCU\\Software\\Microsoft\\Windows NT\\CurrentVersion\\Fonts" /v "%s (TrueType)" /t REG_SZ /d "%s" /f >nul', font.name, path)
    end
  end
  if #registry > 0 then os.execute(table.concat(registry, " & ")) end
  return families
end

local function fontNote(families)
  if #families == 0 then return "" end
  if #families == 1 then return "\n\nThe " .. families[1] .. " font was installed too." end
  return "\n\nThe fonts " .. table.concat(families, ", ", 1, #families - 1) .. " and " .. families[#families] .. " were installed too."
end

local function install()
  local previous = installedVersion()
  ensureWritable()
  -- start from clean folders so files from an older version don't linger
  for _, dir in ipairs({ "main", "dist", "assets", "fonts" }) do
    if not removeTree(join(TARGET, dir)) then
      error("Couldn't replace the old files in " .. join(TARGET, dir) .. ". Close the Onyx Captions window and try again.", 0)
    end
  end
  for _, file in ipairs(FILES) do
    writeFile(join(TARGET, (file.path:gsub("/", SEP))), decode(file.data))
  end
  -- the module is locked while the extension is open; it only changes with Resolve updates
  local module = readFile(SDK_MODULE)
  local target = join(TARGET, "WorkflowIntegration.node")
  if readFile(target) ~= module then
    local ok, err = pcall(writeFile, target, module)
    if not ok then error("Couldn't update WorkflowIntegration.node. Close the Onyx Captions window and try again.", 0) end
  end
  -- the extension works without them, so a failure here only adds a note
  local fontsOk, families = pcall(installFonts)
  if not fontsOk then log("fonts: " .. tostring(families)) end
  local note = fontsOk and fontNote(families)
    or "\n\nThe caption fonts couldn't be installed, so the styles use fonts this computer already has."
  if previous == VERSION then
    return "Onyx Captions " .. VERSION .. " was reinstalled." .. note .. "\n\nRestart DaVinci Resolve if the Onyx Captions window was open."
  elseif previous then
    return string.format("Onyx Captions was updated from %s to %s.", previous, VERSION) .. note .. "\n\nRestart DaVinci Resolve to use the new version."
  end
  return "Onyx Captions " .. VERSION .. " is installed." .. note .. "\n\nRestart DaVinci Resolve, then open Workspace > Workflow Integrations > Onyx Captions."
end

local function uninstall()
  if bmd.direxists(TARGET) then ensureWritable() end
  if not removeTree(TARGET) then
    error("Some files couldn't be removed from " .. TARGET .. ". Close the Onyx Captions window, then try again.", 0)
  end
  return "Onyx Captions is uninstalled. Restart DaVinci Resolve to remove it from the Workflow Integrations menu.\n\n"
    .. "The caption fonts stay installed, so your projects keep their look. "
    .. "Your license stays activated on this computer. To use it on another computer instead, "
    .. "reinstall Onyx Captions and choose Deactivate this computer in its license screen."
end

local function run(action)
  local ok, msg = pcall(action == "uninstall" and uninstall or install)
  log(msg)
  return ok, msg
end

local function main()
  -- automated runs: no window
  if AUTO then
    local why = problem()
    local ok, msg = false, why
    if not why then ok, msg = run(AUTO) end
    F:SetData("OnyxCaptionsInstaller.Result", { ok = ok, message = msg or "", installed = installedVersion() or "" })
    return
  end

  local ui = F.UIManager
  local disp = bmd.UIDispatcher(ui)
  local win = disp:AddWindow({
    ID = "OnyxCaptionsInstaller",
    WindowTitle = "Onyx Captions " .. VERSION,
    Geometry = { 200, 200, 480, 220 },
    ui:VGroup({
      ui:Label({ ID = "Title", Text = "<b>Onyx Captions " .. VERSION .. "</b>", Weight = 0 }),
      ui:Label({ ID = "Message", WordWrap = true, Alignment = { AlignTop = true, AlignLeft = true } }),
      ui:HGroup({
        Weight = 0,
        ui:HGap(0, 1),
        ui:Button({ ID = "Uninstall", Text = "Uninstall" }),
        ui:Button({ ID = "Install", Text = "Install" }),
        ui:Button({ ID = "Close", Text = "Cancel" }),
      }),
    }),
  })
  local items = win:GetItems()

  local function finished(ok, msg)
    items.Message.Text = ok and msg or ("Something went wrong: " .. msg)
    items.Install.Hidden = true
    items.Uninstall.Hidden = true
    items.Close.Text = "Close"
  end

  local why = problem()
  local current = installedVersion()
  if why then
    items.Message.Text = why
    items.Install.Hidden = true
    items.Uninstall.Hidden = true
    items.Close.Text = "Close"
  elseif current then
    items.Message.Text = (current == VERSION and "Onyx Captions " .. current .. " is already installed. You can reinstall or uninstall it."
      or "Onyx Captions " .. current .. " is installed. Update it to " .. VERSION .. ", or uninstall it.")
      .. "\n\nClose the Onyx Captions window first if it's open."
    items.Install.Text = current == VERSION and "Reinstall" or "Update"
  else
    items.Message.Text = "This installs the Onyx Captions extension into DaVinci Resolve Studio."
    items.Uninstall.Hidden = true
  end

  function win.On.Install.Clicked(ev)
    finished(run("install"))
  end

  function win.On.Uninstall.Clicked(ev)
    finished(run("uninstall"))
  end

  function win.On.Close.Clicked(ev)
    disp:ExitLoop()
  end

  function win.On.OnyxCaptionsInstaller.Close(ev)
    disp:ExitLoop()
  end

  win:Show()
  disp:RunLoop()
  win:Hide()
end

